@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Manrope:wght@400;500;600;700;800&display=swap');
:root{--bg:#07111f;--panel:#101d2e;--panel2:#142338;--muted:#92a0b2;--white:#f5f8ff;--blue:#5b9cff;--cyan:#68d6ff;--line:rgba(255,255,255,.09);--gold:#e4c875;--font:'DM Sans',sans-serif;--display:'Manrope',sans-serif}*{box-sizing:border-box}html{background:var(--bg);scroll-behavior:smooth}body{margin:0;color:var(--white);font-family:var(--font);background:var(--bg);min-height:100vh;overflow-x:hidden}button{font:inherit;color:inherit;border:0;cursor:pointer}button:focus-visible{outline:2px solid #8fc5ff;outline-offset:3px}.app{min-height:100vh;position:relative;overflow:hidden;background:radial-gradient(ellipse at 68% 0%,rgba(34,74,135,.19),transparent 40%),linear-gradient(140deg,#081321,#0a1422 45%,#07111d)}.ambient{position:absolute;border-radius:50%;filter:blur(100px);pointer-events:none;opacity:.16}.ambient-one{width:420px;height:420px;background:#1f71ca;right:-170px;top:170px}.ambient-two{width:360px;height:360px;background:#492f88;left:-250px;bottom:-180px}.screen{display:none;min-height:calc(100vh - 106px);animation:screenIn .55s cubic-bezier(.2,.8,.2,1) both}.screen.active{display:block}@keyframes screenIn{from{opacity:0;transform:translateY(12px)}to{opacity:1;transform:translateY(0)}}.topbar{height:74px;padding:0 6.1vw;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid rgba(255,255,255,.07);position:relative;z-index:5;background:rgba(7,16,29,.72);backdrop-filter:blur(18px)}.topbar[hidden],.system-footer[hidden]{display:none}.brand{display:flex;align-items:center;gap:12px;background:none;padding:0}.brand-mark{font:800 21px var(--display);letter-spacing:-2px;color:#fff}.brand-mark span{color:#65baff}.brand-name{font:600 14px var(--display);letter-spacing:.01em}.main-nav{display:flex;align-self:stretch;gap:32px}.nav-link{position:relative;background:none;color:#aab6c6;font-size:13px;font-weight:600;padding:0 2px;transition:color .2s}.nav-link:hover,.nav-link.active{color:#fff}.nav-link.active:after{content:'';position:absolute;bottom:0;left:0;right:0;height:2px;background:#72b9ff;box-shadow:0 0 14px #4ea4ff}.top-actions{display:flex;align-items:center;gap:20px}.icon-btn{background:none;color:#cbd6e5;font-size:27px;line-height:1}.user-chip{display:flex;align-items:center;gap:9px;padding:6px 10px 6px 6px;border:1px solid var(--line);border-radius:24px;background:rgba(255,255,255,.04);font-size:12px}.avatar{display:grid;place-items:center;border-radius:50%;background:linear-gradient(145deg,#96a6ff,#5741b8);color:#fff;font:700 22px var(--display);box-shadow:0 0 24px rgba(107,117,255,.3)}.avatar.small{width:27px;height:27px;font-size:13px}.chevron{color:#8f9db0;font-size:17px}.muted{color:var(--muted);font-size:14px}.eyebrow{font-size:9px;font-weight:700;letter-spacing:.17em;color:#a9bad0;display:flex;align-items:center;gap:9px}.eyebrow i{width:6px;height:6px;border-radius:50%;background:#74bdff;box-shadow:0 0 10px #74bdff}.count{font:600 11px var(--font);color:#7c8ca1;vertical-align:middle;margin-left:4px}.primary-btn,.secondary-btn{display:inline-flex;align-items:center;justify-content:center;gap:18px;border-radius:5px;padding:12px 19px;font-size:12px;font-weight:700;transition:transform .2s,box-shadow .2s,background .2s}.primary-btn{background:#f5f8ff;color:#081526;box-shadow:0 6px 20px rgba(0,0,0,.2)}.primary-btn:hover{transform:translateY(-2px);box-shadow:0 8px 26px rgba(116,188,255,.2)}.primary-btn span{font-size:17px;font-weight:400}.secondary-btn{border:1px solid rgba(255,255,255,.19);background:rgba(255,255,255,.04);color:#d8e2ef}.secondary-btn:hover{background:rgba(255,255,255,.1)}.text-link{background:none;color:#d4e5fb;font-size:11px;font-weight:600}.text-link span{margin-left:8px;color:#76bcff;font-size:16px}.system-footer{height:32px;padding:0 6.1vw;display:flex;align-items:center;justify-content:space-between;position:relative;z-index:3;color:#8998aa;font-size:10px;border-top:1px solid rgba(255,255,255,.05);background:rgba(6,14,24,.4)}.tiny-ps{font:700 10px var(--display);letter-spacing:-1px;color:#9ebfee}.footer-center{display:flex;gap:7px;align-items:center}.status-dot{display:inline-block;width:6px;height:6px;background:#71dfa4;border-radius:50%;box-shadow:0 0 8px rgba(113,223,164,.8)}.footer-divider{color:#34445a}
/* power-on welcome */
.welcome-screen{min-height:100vh!important;position:relative;display:none!important;padding:0 8.3vw}.welcome-screen.active{display:flex!important;align-items:center}.welcome-copy{position:relative;z-index:2;width:47%;padding-bottom:45px}.welcome-copy .eyebrow{margin-bottom:25px}.welcome-copy h1,.profile-content h1,.page-heading h1,.store-copy h1{font:600 clamp(48px,6.1vw,82px)/1.04 var(--display);letter-spacing:-.07em;margin:0 0 18px}.welcome-copy h1 em,.store-copy h1 em{font-style:normal;color:#74bdff}.welcome-copy>p{font-size:15px;color:#a1aec0;margin:0 0 37px}.power-button{display:flex;align-items:center;gap:15px;background:#eef5ff;color:#0a1828;border-radius:5px;padding:0 15px 0 5px;height:52px;font-weight:700;font-size:12px;box-shadow:0 8px 30px rgba(73,154,255,.2);transition:.25s}.power-button:hover{transform:translateY(-3px);box-shadow:0 13px 35px rgba(73,154,255,.38)}.power-symbol{width:42px;height:42px;display:grid;place-items:center;border-radius:4px;background:#0b1c31;color:#83c9ff;font-size:25px}.button-arrow{margin-left:17px;font-size:17px}.welcome-foot{display:flex;align-items:center;gap:10px;margin-top:18px;color:#8694a7;font-size:10px}.welcome-foot .tiny-ps{font-size:13px}.welcome-foot kbd{font:600 9px var(--font);border:1px solid #44546a;border-radius:3px;padding:2px 5px;color:#b8c5d5}.console-stage{position:absolute;right:4%;top:8%;width:51%;height:78%;display:flex;align-items:center;justify-content:center;perspective:900px}.halo{position:absolute;width:480px;height:480px;border:1px solid rgba(95,164,255,.12);border-radius:50%;box-shadow:0 0 100px rgba(42,120,255,.13),inset 0 0 80px rgba(42,120,255,.08)}.halo:before,.halo:after{content:'';position:absolute;inset:30px;border:1px solid rgba(95,164,255,.1);border-radius:50%}.halo:after{inset:-30px;border-color:rgba(95,164,255,.06)}.console{position:relative;width:355px;height:500px;transform:rotate(-12deg) rotateY(-12deg);filter:drop-shadow(0 28px 45px rgba(0,0,0,.45));animation:consoleFloat 5s ease-in-out infinite}.console-core{position:absolute;z-index:2;left:114px;top:24px;width:132px;height:422px;background:linear-gradient(90deg,#d9e3ee 0%,#fcfdff 18%,#f8fbff 76%,#c9d6e5 100%);border-radius:22px 22px 17px 17px;box-shadow:inset -12px 0 18px rgba(39,70,109,.14),inset 8px 0 12px rgba(255,255,255,.8)}.console-wing{position:absolute;top:0;width:125px;height:425px;background:linear-gradient(90deg,#101d32,#1d2c43 40%,#111d2d);clip-path:polygon(10% 0,100% 7%,100% 94%,0 100%,0 12%);border:1px solid rgba(179,210,255,.2);box-shadow:inset 0 0 14px rgba(131,180,255,.1)}.left-wing{left:12px;transform:rotate(-5deg);border-radius:40% 4% 2% 20%}.right-wing{right:7px;transform:scaleX(-1) rotate(-5deg);border-radius:40% 4% 2% 20%}.console-glow{position:absolute;left:10px;right:10px;top:42px;height:200px;background:linear-gradient(180deg,rgba(48,142,255,.34),transparent);filter:blur(12px)}.console-slit{position:absolute;left:14px;right:14px;bottom:54px;height:3px;border-radius:5px;background:#142236;box-shadow:0 0 0 1px rgba(255,255,255,.3)}.console-mark{position:absolute;bottom:20px;right:17px;font:700 10px var(--display);letter-spacing:.2em;color:#73859a}.console-base{position:absolute;z-index:3;bottom:32px;left:108px;width:149px;height:25px;border-radius:50%;background:linear-gradient(180deg,#394a5d,#101927);box-shadow:0 10px 17px rgba(0,0,0,.5)}@keyframes consoleFloat{0%,100%{transform:rotate(-12deg) rotateY(-12deg) translateY(0)}50%{transform:rotate(-12deg) rotateY(-12deg) translateY(-12px)}}.stage-caption{position:absolute;bottom:4%;left:10%;right:8%;display:flex;justify-content:space-between;color:#71849a;font-size:8px;letter-spacing:.18em}.welcome-bottom{position:absolute;bottom:25px;left:8.3vw;right:8.3vw;display:flex;justify-content:space-between;color:#6d7b8f;font-size:9px;letter-spacing:.09em}.welcome-bottom b{color:#4d8bc7}
/* profile */
.profile-screen{position:relative;min-height:calc(100vh - 106px);overflow:hidden}.profile-backdrop{position:absolute;inset:0;background:radial-gradient(ellipse at 75% 65%,rgba(51,102,181,.25),transparent 34%),radial-gradient(ellipse at 25% 80%,rgba(39,81,138,.13),transparent 42%)}.profile-content{position:relative;z-index:2;padding:15vh 0 0 13vw}.profile-content .eyebrow{margin-bottom:20px}.profile-content h1{font-size:48px;letter-spacing:-.055em;margin-bottom:8px}.profile-content>p{margin:0 0 32px}.profile-card{display:flex;align-items:center;gap:17px;width:355px;padding:15px;text-align:left;background:rgba(20,37,59,.78);border:1px solid rgba(125,179,255,.22);border-radius:7px;box-shadow:0 18px 50px rgba(0,0,0,.18);transition:.25s}.profile-card:hover{transform:translateX(5px);border-color:#6ebaff;background:rgba(27,48,75,.9)}.profile-avatar{width:52px;height:52px;font-size:26px}.profile-info{display:flex;flex-direction:column;gap:5px;flex:1}.profile-info strong{font:700 15px var(--display)}.profile-info small{color:#9aabc0;font-size:11px}.profile-chevron{font-size:22px;color:#8dc7ff}.profile-hint{display:flex;gap:35px;margin-top:18px;color:#74869d;font-size:10px}.profile-hint b{color:#cedaeb}.profile-console-glow{position:absolute;width:470px;height:470px;border-radius:50%;right:13%;top:12%;border:1px solid rgba(118,179,255,.1);box-shadow:0 0 100px rgba(34,114,224,.13),inset 0 0 100px rgba(34,114,224,.08)}
/* dashboard */
.dashboard-inner,.library-screen,.plus-screen,.store-screen,.downloads-screen{padding:42px 6.1vw 55px;position:relative}.greeting-row{display:flex;justify-content:space-between;align-items:center;margin-bottom:26px}.greeting-row .eyebrow{margin-bottom:9px}.greeting-row h1{font:600 29px var(--display);letter-spacing:-.05em;margin:0 0 5px}.wave{font-size:20px;color:#8fcaff}.greeting-row p{margin:0}.status-pill{display:flex;align-items:center;gap:8px;padding:8px 11px;border:1px solid rgba(255,255,255,.1);border-radius:20px;color:#aab9ca;font-size:10px;background:rgba(255,255,255,.025)}.feature-row{display:grid;grid-template-columns:1.75fr .8fr;gap:15px;height:260px}.feature-card{position:relative;overflow:hidden;border-radius:8px;background:#112540}.hero-art{position:absolute;inset:0;overflow:hidden}.art-fortnite{background:radial-gradient(ellipse at 75% 53%,rgba(255,174,90,.56),transparent 25%),radial-gradient(ellipse at 56% 24%,rgba(255,212,143,.55),transparent 27%),linear-gradient(125deg,#2c9cce 0%,#287eb7 36%,#753c8a 72%,#ee865e 100%)}.art-fortnite:before{content:'';position:absolute;inset:0;background:linear-gradient(180deg,rgba(7,15,28,.02),rgba(7,15,28,.78)),repeating-linear-gradient(130deg,transparent 0 90px,rgba(255,255,255,.06) 91px 92px)}.art-orb{position:absolute;width:180px;height:180px;right:17%;top:-22px;border-radius:50%;background:radial-gradient(circle at 30% 30%,#fff5ce,#f3a561 30%,rgba(240,128,86,.1) 68%,transparent 72%);box-shadow:0 0 54px rgba(255,191,119,.4)}.art-silhouette{position:absolute;right:20%;bottom:-27px;width:105px;height:177px;background:linear-gradient(110deg,#161b36,#302449 58%,#11192e);clip-path:polygon(37% 0,64% 4%,78% 15%,72% 25%,94% 31%,100% 38%,78% 43%,84% 61%,100% 100%,59% 100%,48% 72%,38% 100%,0 100%,18% 63%,26% 40%,10% 34%,19% 28%,35% 24%);filter:drop-shadow(0 0 12px rgba(0,0,0,.4))}.art-label{position:absolute;right:5%;top:15%;font:800 22px var(--display);letter-spacing:.18em;color:rgba(255,255,255,.58);transform:rotate(-90deg);transform-origin:right top}.hero-overlay{position:absolute;inset:0;background:linear-gradient(90deg,rgba(5,15,28,.9),rgba(5,15,28,.36) 45%,transparent 76%)}.hero-content{position:absolute;left:28px;bottom:25px;z-index:1}.tag{font-size:8px;font-weight:700;letter-spacing:.16em;color:#b3d9ff}.hero-content h2{font:700 29px var(--display);letter-spacing:-.04em;margin:8px 0 4px}.hero-content p{font-size:11px;color:#d1dce9;margin:0 0 14px}.hero-content .primary-btn{padding:9px 14px;font-size:10px}.hero-pagination{position:absolute;right:22px;bottom:22px;display:flex;gap:5px}.hero-pagination i{width:5px;height:5px;border-radius:5px;background:rgba(255,255,255,.4)}.hero-pagination i.selected{width:18px;background:#fff}.side-feature{background:rgba(16,30,47,.8);border:1px solid var(--line);border-radius:8px;padding:18px 18px 13px;display:flex;flex-direction:column}.side-feature .eyebrow{font-size:8px}.console-status{display:flex;align-items:center;gap:11px;margin-top:12px}.mini-console{width:34px;height:34px;border-radius:6px;background:linear-gradient(135deg,#dce7f5,#8b9db2);color:#14253b;display:grid;place-items:center;font:800 11px var(--display)}.console-status b,.recent-game b{display:block;font:600 11px var(--display)}.console-status small,.recent-game small{display:block;color:#8798ac;font-size:9px;margin-top:4px}.online-dot{margin-left:auto;width:6px;height:6px;background:#65dba0;border-radius:50%;box-shadow:0 0 8px #65dba0}.side-divider{height:1px;background:var(--line);margin:14px 0 12px}.side-bottom{flex:1}.recent-game{display:flex;align-items:center;gap:9px;margin-top:10px}.mini-art{width:35px;height:35px;border-radius:5px;display:grid;place-items:center;font:800 11px var(--display);color:#eaf5ff}.art-rocket{background:linear-gradient(135deg,#1dd3e4,#2452a3)}.art-soccer{background:linear-gradient(135deg,#a5d84c,#177450)}.recent-game>div:nth-child(2){flex:1}.recent-game button,.quick-widget button{background:none;color:#8fa4bf;font-size:16px}.section-heading{display:flex;justify-content:space-between;align-items:end;margin:27px 0 12px}.section-heading .eyebrow{font-size:8px;margin-bottom:5px}.section-heading h2,.library-title h2,.store-toolbar h2,.downloads-header h2{font:700 17px var(--display);margin:0;letter-spacing:-.025em}.game-strip{display:grid;grid-template-columns:repeat(5,1fr);gap:12px}.game-card{min-width:0;cursor:pointer;transition:transform .22s}.game-card:hover{transform:translateY(-4px)}.game-cover{height:118px;border-radius:6px;position:relative;overflow:hidden;display:flex;align-items:end;padding:12px;background:linear-gradient(135deg,#243d67,#141c36);box-shadow:inset 0 0 0 1px rgba(255,255,255,.08)}.game-cover:before{content:'';position:absolute;inset:0;background:linear-gradient(180deg,transparent 28%,rgba(5,10,19,.78))}.cover-title{position:relative;z-index:1;font:800 16px/1 var(--display);letter-spacing:-.05em;text-shadow:0 2px 9px #000}.cover-fortnite{background:radial-gradient(circle at 75% 35%,#ffd777,#e67840 23%,transparent 38%),linear-gradient(135deg,#4ec1db,#564691 65%,#261c48)}.cover-rocket{background:radial-gradient(ellipse at 70% 55%,#28ecff,transparent 28%),linear-gradient(135deg,#087dba,#15205b 60%,#151a3c)}.cover-roblox{background:radial-gradient(circle at 70% 25%,#ff7552,transparent 25%),linear-gradient(135deg,#ed2e3b,#991c42 60%,#36234a)}.cover-fc{background:radial-gradient(ellipse at 75% 25%,#a7f772,transparent 25%),linear-gradient(130deg,#258f72,#101c43 75%)}.cover-spider{background:radial-gradient(circle at 65% 32%,#ff3e48,transparent 29%),linear-gradient(135deg,#171c35,#172968 68%,#5f214d)}.cover-rocket .cover-title{font-style:italic;letter-spacing:.05em}.cover-roblox .cover-title{font-size:24px;letter-spacing:-.1em}.cover-fc .cover-title{font-size:23px}.cover-spider .cover-title{font-size:13px;letter-spacing:.12em}.game-card-meta{display:flex;justify-content:space-between;align-items:center;padding:8px 2px 0}.game-card-meta b{font-size:10px;font-weight:600}.game-card-meta small{font-size:9px;color:#8493a7}.dashboard-lower{display:grid;grid-template-columns:1.5fr .8fr;gap:12px;margin-top:19px}.promo-banner,.quick-widget{position:relative;overflow:hidden;display:flex;align-items:center;gap:13px;text-align:left;padding:13px 17px;border-radius:7px;background:linear-gradient(105deg,rgba(35,51,86,.9),rgba(21,32,58,.92));border:1px solid rgba(166,168,255,.1)}.plus-icon{width:31px;height:31px;border-radius:7px;background:linear-gradient(145deg,#ad8cff,#5d4cb4);display:grid;place-items:center;font:400 27px var(--display)}.promo-banner>span:nth-child(2),.quick-widget>span:nth-child(2){display:flex;flex-direction:column;gap:4px;flex:1;position:relative;z-index:1}.promo-banner b,.quick-widget b{font:600 11px var(--display)}.promo-banner small,.quick-widget small{font-size:9px;color:#a1abc1}.promo-arrow{font-size:17px;color:#b6a4ff;position:relative;z-index:1}.banner-glow{position:absolute;width:180px;height:120px;border-radius:50%;background:#6451b3;filter:blur(60px);right:10%;opacity:.25}.quick-widget{background:rgba(16,30,47,.8)}.widget-icon{font-size:20px;color:#86c5ff}

