.widget-icon{font-size:20px;color:#86c5ff}
/* library */
.library-screen{padding-top:38px}.page-heading{display:flex;align-items:end;justify-content:space-between;margin-bottom:26px}.page-heading .eyebrow{margin-bottom:10px}.page-heading h1{font-size:37px;letter-spacing:-.06em;margin:0 0 5px}.page-heading p{margin:0}.library-tools{display:flex;align-items:center;gap:8px}.filter-btn,.sort-btn{background:rgba(255,255,255,.035);border:1px solid var(--line);border-radius:4px;padding:8px 11px;color:#9daec2;font-size:10px}.filter-btn.active{background:#e8f2ff;color:#0b1a2c;border-color:#e8f2ff;font-weight:700}.filter-btn span{margin-left:7px;opacity:.7}.sort-btn{margin-left:8px}.sort-btn span{margin-left:16px}.library-feature{display:grid;grid-template-columns:1.04fr 1fr;min-height:220px;border-radius:8px;overflow:hidden;background:linear-gradient(110deg,#142944,#101d30);border:1px solid var(--line)}.library-feature-art{position:relative;min-height:220px;overflow:hidden}.library-feature-art .art-orb{width:160px;height:160px;right:22%;top:10px}.library-feature-art .art-silhouette{right:25%;height:160px}.library-feature-copy{padding:24px 28px}.library-feature-copy .tag{font-size:8px}.library-feature-copy h2{font:700 27px var(--display);letter-spacing:-.05em;margin:8px 0}.library-feature-copy>p{max-width:510px;color:#a8b7c9;font-size:11px;line-height:1.65;margin:0 0 14px}.game-meta{display:flex;align-items:center;gap:17px;font-size:9px;color:#9bacc0}.installed-tag{color:#7ee0aa}.feature-buttons{display:flex;gap:9px;margin-top:16px}.feature-buttons .primary-btn,.feature-buttons .secondary-btn{padding:9px 13px;font-size:10px}.library-title{display:flex;justify-content:space-between;align-items:center;margin:25px 0 13px}.library-title h2{font-size:16px}.library-title>.muted{font-size:10px}.library-grid{display:grid;grid-template-columns:repeat(5,1fr);gap:17px 13px}.library-grid .game-cover{height:160px}.game-card .game-cover .cover-badge{position:absolute;z-index:2;right:9px;top:9px;border-radius:3px;padding:4px 6px;background:rgba(7,14,24,.75);font-size:8px;color:#d4e8ff}.game-card.hidden{display:none}
