y{padding:28px 22px;width:100%}.plus-copy h1{font-size:35px}.plus-copy>p{max-width:280px}.plus-art{inset:35% 0 0 20%;opacity:.72}.disc-one{width:105px;height:105px;font-size:48px}.disc-two{width:75px;height:75px;font-size:35px}.disc-three{width:57px;height:57px;font-size:28px}.plus-orbit{width:300px;height:300px;right:0}.membership-row{display:block}.membership-row>div:first-child{margin-bottom:17px}.tier-cards{grid-template-columns:1fr}.tier-card{min-height:106px}.store-hero{min-height:370px}.store-copy{padding:28px 22px}.store-copy h1{font-size:37px}.store-art{right:-12%;top:28%;height:85%;width:100%;opacity:.72}.store-box{right:28%;width:110px;height:130px;font-size:15px}.store-ring{width:230px;height:230px;right:14%}.ring-two{width:170px;height:280px;right:24%}.store-note{font-size:7px}.store-toolbar{align-items:flex-start;flex-direction:column;gap:12px}.store-categories{width:100%;justify-content:space-between}.downloads-screen .page-heading{align-items:flex-start}.downloads-screen .page-heading .secondary-btn{align-self:flex-start}.system-card{gap:10px;padding:12px}.system-icon{width:33px;height:33px}.up-to-date{font-size:0}.up-to-date i{width:7px;height:7px}.system-copy p{font-size:8px}.download-tip{align-items:flex-start}.tip-status{display:none}.modal{padding:24px}.game-modal-art{margin:-24px -24px 20px}.game-play-area{height:210px}.welcome-bottom span:first-child{display:none}}

