35: function coverMarkup(game,extra=''){
36:  const label=game.label||game.name.toUpperCase();
37:  return `<div class="game-cover cover-${game.art||'fortnite'} ${extra}"><span class="cover-title">${label}</span>${game.installed===false?'<span class="cover-badge">＋ Get</span>':''}</div>`;
38: }
39: function gameCard(game){return `<article class="game-card" data-open-game="${game.id}">${coverMarkup(game)}<div class="game-card-meta"><b>${game.name}</b><small>${game.kind||game.genre}</small></div></article>`}
40: function renderHomeGames(){ $('#home-games').innerHTML=games.map(gameCard).join(''); }
41: function renderLibrary(){
42:  let list=sortDescending?[...games].reverse():games;
43:  $('#library-grid').innerHTML=list.map(game=>`<article class="game-card ${currentFilter==='installed'&&!game.installed?'hidden':''}" data-open-game="${game.id}">${coverMarkup(game)}<div class="game-card-meta"><b>${game.name}</b><small>${game.installed?'✓ '+game.played:'＋ Download to play'}</small></div></article>`).join('');
44:  $$('.filter-btn').forEach(btn=>btn.classList.toggle('active',btn.dataset.filter===currentFilter));
45: }
46: function renderStore(){
47:  let list=storeGames.filter(game=>storeCategory==='Featured'?game.category==='Featured':storeCategory==='New releases'?game.category==='New releases':game.category==='Deals');
48:  $('#store-grid').innerHTML=list.map((game,i)=>`<article class="store-card" data-store-game="${game.name}"><span class="store-price">${game.price}</span><div class="game-cover ${game.art}"><span class="cover-title">${game.label}</span></div><div class="store-card-info"><b>${game.name}</b><small>${game.price==='Free'?'Free to play':'PS5 · Full game'}</small></div></article>`).join('');
49:  $$('.category-btn').forEach(b=>b.classList.toggle('active',b.dataset.category===storeCategory));
50: }
51: function renderDownloads(){
52:  $('#download-count').textContent=queue.filter(q=>q.status!=='complete').length;
53:  $('#empty-downloads').hidden=queue.length>0;
54:  $('#download-list').innerHTML=queue.map(q=>`<div class="download-item"><div class="mini-art art-${q.art||'rocket'}">${q.label||'PS'}</div><div class="download-detail"><div class="download-detail-top"><b>${q.name}</b><small>${q.status==='complete'?'Completed':q.paused?'Paused':q.kind==='system'?'Downloading system software':'Downloading'}</small></div><div class="download-progress"><span style="width:${q.progress}%"></span></div><div class="download-size"><span>${q.status==='complete'?'Ready to play':q.progress+'% complete'}</span><span>${q.status==='complete'?'Installed':q.paused?'Paused':`${q.left||q.size} · ${q.speed||'28.4 MB/s'}`}</span></div></div>${q.status==='complete'?'<span class="installed-tag">✓</span>':`<button class="download-action" data-download-control="${q.id}" aria-label="${q.paused?'Resume':'Pause'} download">${q.paused?'▶':'Ⅱ'}</button>`}</div>`).join('');
55:  $('#quick-downloads').textContent=queue.some(q=>q.status==='active')?`${queue.filter(q=>q.status==='active').length} download in progress`:'You’re all caught up';
56: }
57: function addDownload(game,kind='game'){
58:  if(queue.find(q=>q.name===game.name&&q.status!=='complete')){showToast(`${game.name} is already in your downloads`);showScreen('downloads');return}
59:  const entry={id:Date.now()+Math.random(),name:game.name,art:game.art||'rocket',label:game.label||'PS',size:game.size||'12.8 GB',left:game.size||'12.8 GB',progress:0,status:'active',kind};queue.unshift(entry);renderDownloads();showToast(`${game.name} added to downloads`);showScreen('downloads');
60:  const tick=()=>{if(entry.status!=='active')return;entry.progress=Math.min(100,entry.progress+Math.ceil(Math.random()*4+1));entry.left=entry.progress>75?'2.1 GB':entry.progress>45?'5.8 GB':entry.progress>15?'9.4 GB':entry.size;entry.speed=(24+Math.random()*18).toFixed(1)+' MB/s';if(entry.progress>=100){entry.status='complete';entry.left='';clearInterval(timers.get(entry.id));timers.delete(entry.id);showToast(`${entry.name} is ready to play`)}renderDownloads()};
61:  timers.set(entry.id,setInterval(tick,520));
62: }
